import type { Status } from "@/registry/default/instruments/status-badge";

export const STUDIES = ["NORDIC-2", "ACUTE-1", "TREAT-7", "RENAL-4"] as const;

export type Study = (typeof STUDIES)[number];

export const STUDY_TITLE: Record<Study, string> = {
  "NORDIC-2": "Nordic cohort follow-up",
  "ACUTE-1": "Acute infection panel",
  "TREAT-7": "Treatment response",
  "RENAL-4": "Renal function study",
};

export const SAMPLE_KINDS = [
  "Serum",
  "Plasma",
  "Tissue",
  "DNA",
  "RNA",
  "Urine",
] as const;

export type SampleKind = (typeof SAMPLE_KINDS)[number];

export const REGISTRY_STATUSES = [
  "stored",
  "in-use",
  "quarantined",
  "consumed",
  "destroyed",
] as const;

export type RegistryStatus = (typeof REGISTRY_STATUSES)[number];

export const STATUS_LABEL: Record<RegistryStatus, string> = {
  stored: "Stored",
  "in-use": "In use",
  quarantined: "Quarantined",
  consumed: "Consumed",
  destroyed: "Destroyed",
};

export const STATUS: Record<RegistryStatus, Status> = {
  stored: "success",
  "in-use": "running",
  quarantined: "warning",
  consumed: "idle",
  destroyed: "idle",
};

export type StorageLocation = {
  /** Freezer, e.g. "F2". */
  freezer: string;
  /** Rack, e.g. "R3". */
  rack: string;
  /** Box, e.g. "B12". */
  box: string;
  /** Position inside the box, e.g. "A4". */
  position: string;
};

export type Aliquot = {
  id: string;
  /** Remaining volume in µL. Null when it was not recorded. */
  volumeUl: number | null;
  location: string;
  status: "stored" | "in-use" | "consumed";
};

/**
 * The most recent custody event. Earlier events — collected, accessioned,
 * stored — are derived from the record so the mock adapter cannot disagree
 * with itself.
 */
export type LastAction = {
  kind: "retrieved" | "quarantined" | "depleted" | "destroyed" | "verified";
  /** ISO 8601 timestamp. */
  at: string;
  actor: string;
  note?: string;
};

export type RegistrySample = {
  id: string;
  accession: string;
  study: Study;
  kind: SampleKind;
  /** De-identified participant identifier. */
  subject: string;
  status: RegistryStatus;
  /** ISO 8601 timestamp. */
  collectedAt: string;
  /** ISO 8601 timestamp. */
  receivedAt: string;
  /** ISO 8601 timestamp. */
  storedAt: string;
  location: StorageLocation;
  /** Remaining volume in µL. Null when it was not recorded. */
  volumeUl: number | null;
  aliquots: readonly Aliquot[];
  custodian: string;
  /** Parent sample for derived material, e.g. DNA from a serum sample. */
  parentId: string | null;
  runIds: readonly string[];
  note?: string;
  quarantineReason?: string;
  lastAction: LastAction | null;
};

export type RegistryFilters = {
  query: string;
  study: "all" | Study;
  kind: "all" | SampleKind;
  status: "all" | RegistryStatus;
};

export function isStudy(value: string | null): value is Study {
  return value !== null && STUDIES.includes(value as Study);
}

export function isSampleKind(value: string | null): value is SampleKind {
  return value !== null && SAMPLE_KINDS.includes(value as SampleKind);
}

export function isRegistryStatus(
  value: string | null,
): value is RegistryStatus {
  return value !== null && REGISTRY_STATUSES.includes(value as RegistryStatus);
}

import {
  type RegistryFilters,
  type RegistrySample,
  STATUS_LABEL,
  STUDY_TITLE,
} from "./types";

export function filterSamples(
  samples: readonly RegistrySample[],
  filters: RegistryFilters,
): RegistrySample[] {
  const term = filters.query.trim().toLowerCase();
  return samples.filter((sample) => {
    if (filters.study !== "all" && sample.study !== filters.study) {
      return false;
    }
    if (filters.kind !== "all" && sample.kind !== filters.kind) {
      return false;
    }
    if (filters.status !== "all" && sample.status !== filters.status) {
      return false;
    }
    if (!term) {
      return true;
    }
    const haystack = [
      sample.id,
      sample.accession,
      sample.subject,
      sample.study,
      STUDY_TITLE[sample.study],
      sample.kind,
      STATUS_LABEL[sample.status],
      formatLocation(sample.location),
      sample.custodian,
      sample.parentId ?? "",
      sample.runIds.join(" "),
      sample.note ?? "",
      sample.quarantineReason ?? "",
    ]
      .join(" ")
      .toLowerCase();
    return haystack.includes(term);
  });
}

export type RegistrySummary = {
  count: number;
  stored: number;
  inUse: number;
  quarantined: number;
  consumed: number;
  destroyed: number;
  missingVolume: number;
};

export function summarize(samples: readonly RegistrySample[]): RegistrySummary {
  return {
    count: samples.length,
    stored: samples.filter((sample) => sample.status === "stored").length,
    inUse: samples.filter((sample) => sample.status === "in-use").length,
    quarantined: samples.filter((sample) => sample.status === "quarantined")
      .length,
    consumed: samples.filter((sample) => sample.status === "consumed").length,
    destroyed: samples.filter((sample) => sample.status === "destroyed").length,
    missingVolume: samples.filter((sample) => sample.volumeUl === null).length,
  };
}

const DATE_FORMATTER = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

const SHORT_DATE_FORMATTER = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
});

const TIME_FORMATTER = new Intl.DateTimeFormat("en-GB", {
  hour: "2-digit",
  minute: "2-digit",
  hourCycle: "h23",
  timeZone: "UTC",
});

const DATE_TIME_FORMATTER = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  hour: "2-digit",
  minute: "2-digit",
  hourCycle: "h23",
  timeZone: "UTC",
});

const NUMBER_FORMATTER = new Intl.NumberFormat("en-GB");

export function formatDate(iso: string): string {
  return DATE_FORMATTER.format(new Date(iso));
}

export function formatShortDate(iso: string): string {
  return SHORT_DATE_FORMATTER.format(new Date(iso));
}

export function formatTime(iso: string): string {
  return TIME_FORMATTER.format(new Date(iso));
}

export function formatDateTime(iso: string): string {
  return `${DATE_TIME_FORMATTER.format(new Date(iso))} UTC`;
}

/** Compact timestamp for the custody timeline. Pair it with a UTC note. */
export function formatCustodyTime(iso: string): string {
  return `${SHORT_DATE_FORMATTER.format(new Date(iso))} · ${formatTime(iso)}`;
}

export function formatVolume(value: number | null): string {
  return value === null ? "—" : `${NUMBER_FORMATTER.format(value)} µL`;
}

export function formatLocation(location: RegistrySample["location"]): string {
  return `${location.freezer} · ${location.rack} · ${location.box} · ${location.position}`;
}

export function uniqueStudies(samples: readonly RegistrySample[]): number {
  return new Set(samples.map((sample) => sample.study)).size;
}

function cell(value: string | number | null): string {
  if (value === null) {
    return "";
  }
  const text = String(value);
  return /[",\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

const CSV_HEADER = [
  "sample_id",
  "accession",
  "study",
  "kind",
  "subject",
  "status",
  "freezer",
  "rack",
  "box",
  "position",
  "volume_ul",
  "collected_at",
  "received_at",
  "custodian",
  "parent_id",
  "run_ids",
  "note",
].join(",");

export function toCsv(samples: readonly RegistrySample[]): string {
  const rows = samples.map((sample) =>
    [
      sample.id,
      sample.accession,
      sample.study,
      sample.kind,
      sample.subject,
      sample.status,
      sample.location.freezer,
      sample.location.rack,
      sample.location.box,
      sample.location.position,
      sample.volumeUl,
      sample.collectedAt,
      sample.receivedAt,
      sample.custodian,
      sample.parentId,
      sample.runIds.join(" "),
      sample.note ?? sample.quarantineReason ?? "",
    ]
      .map(cell)
      .join(","),
  );
  return [CSV_HEADER, ...rows].join("\n");
}

"use client";

import type * as React from "react";
import { Button } from "@/registry/default/ui/button";
import { Input } from "@/registry/default/ui/input";
import {
  REGISTRY_STATUSES,
  type RegistryFilters,
  SAMPLE_KINDS,
  STATUS_LABEL,
  STUDIES,
} from "./types";

export type FilterRailProps = {
  filters: RegistryFilters;
  onChange: (patch: Partial<RegistryFilters>) => void;
  onReset: () => void;
  activeCount: number;
  studyCounts: Record<"all" | (typeof STUDIES)[number], number>;
  kindCounts: Record<"all" | (typeof SAMPLE_KINDS)[number], number>;
  statusCounts: Record<"all" | (typeof REGISTRY_STATUSES)[number], number>;
};

export function FilterRail({
  filters,
  onChange,
  onReset,
  activeCount,
  studyCounts,
  kindCounts,
  statusCounts,
}: FilterRailProps): React.ReactElement {
  return (
    <aside
      aria-label="Filters"
      className="grid content-start gap-4 border-b p-3 lg:border-e lg:border-b-0 print:hidden"
      data-slot="sample-registry-filters"
    >
      <div className="flex items-center justify-between gap-2">
        <h2 className="font-medium text-sm">Filters</h2>
        <Button
          disabled={activeCount === 0}
          onClick={onReset}
          size="xs"
          type="button"
          variant="ghost"
        >
          Reset
        </Button>
      </div>

      <Input
        aria-label="Filter samples"
        onChange={(event) => onChange({ query: event.target.value })}
        placeholder="Sample, accession, subject…"
        size="sm"
        type="search"
        value={filters.query}
      />

      <fieldset className="min-w-0">
        <legend className="mb-1.5 font-medium text-muted-foreground text-xs">
          Status
        </legend>
        <div className="flex flex-wrap gap-1 lg:grid">
          <FilterButton
            active={filters.status === "all"}
            count={statusCounts.all}
            label="All"
            onClick={() => onChange({ status: "all" })}
          />
          {REGISTRY_STATUSES.map((status) => (
            <FilterButton
              active={filters.status === status}
              count={statusCounts[status]}
              key={status}
              label={STATUS_LABEL[status]}
              onClick={() => onChange({ status })}
            />
          ))}
        </div>
      </fieldset>

      <fieldset className="min-w-0">
        <legend className="mb-1.5 font-medium text-muted-foreground text-xs">
          Study
        </legend>
        <div className="flex flex-wrap gap-1 lg:grid">
          <FilterButton
            active={filters.study === "all"}
            count={studyCounts.all}
            label="All studies"
            onClick={() => onChange({ study: "all" })}
          />
          {STUDIES.map((study) => (
            <FilterButton
              active={filters.study === study}
              count={studyCounts[study]}
              key={study}
              label={study}
              onClick={() => onChange({ study })}
            />
          ))}
        </div>
      </fieldset>

      <fieldset className="min-w-0">
        <legend className="mb-1.5 font-medium text-muted-foreground text-xs">
          Type
        </legend>
        <div className="flex flex-wrap gap-1 lg:grid">
          <FilterButton
            active={filters.kind === "all"}
            count={kindCounts.all}
            label="All types"
            onClick={() => onChange({ kind: "all" })}
          />
          {SAMPLE_KINDS.map((kind) => (
            <FilterButton
              active={filters.kind === kind}
              count={kindCounts[kind]}
              key={kind}
              label={kind}
              onClick={() => onChange({ kind })}
            />
          ))}
        </div>
      </fieldset>

      <p className="hidden text-muted-foreground text-xs leading-relaxed lg:block">
        Filters, sort, and the open sample are kept in the URL. Share the
        address to reproduce this view.
      </p>
    </aside>
  );
}

function FilterButton({
  label,
  count,
  active,
  onClick,
}: {
  label: string;
  count: number;
  active: boolean;
  onClick: () => void;
}): React.ReactElement {
  return (
    <Button
      aria-pressed={active}
      className="justify-between gap-3 lg:w-full"
      onClick={onClick}
      size="xs"
      type="button"
      variant={active ? "secondary" : "ghost"}
    >
      <span className="truncate">{label}</span>
      <span className="font-mono text-muted-foreground text-xs tabular-nums">
        {count}
      </span>
    </Button>
  );
}

"use client";

import { AlertTriangleIcon, ArrowUpRightIcon, InboxIcon } from "lucide-react";
import type * as React from "react";
import {
  type Status,
  StatusBadge,
} from "@/registry/default/instruments/status-badge";
import {
  Timeline,
  type TimelineItem,
} from "@/registry/default/instruments/timeline";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  formatCustodyTime,
  formatDateTime,
  formatLocation,
  formatVolume,
} from "./adapter";
import {
  type Aliquot,
  type LastAction,
  type RegistrySample,
  STATUS,
  STATUS_LABEL,
  STUDY_TITLE,
} from "./types";

const ALIQUOT_LABEL: Record<Aliquot["status"], string> = {
  stored: "Stored",
  "in-use": "In use",
  consumed: "Consumed",
};

const ALIQUOT_STATUS: Record<Aliquot["status"], Status> = {
  stored: "success",
  "in-use": "running",
  consumed: "idle",
};

const ACTION_LABEL: Record<LastAction["kind"], string> = {
  retrieved: "Retrieved",
  quarantined: "Quarantined",
  depleted: "Depleted",
  destroyed: "Destroyed",
  verified: "Volume verified",
};

const ACTION_STATUS: Record<LastAction["kind"], Status> = {
  retrieved: "running",
  quarantined: "warning",
  depleted: "idle",
  destroyed: "idle",
  verified: "success",
};

function buildCustody(sample: RegistrySample): TimelineItem[] {
  const items: TimelineItem[] = [
    {
      id: "collected",
      title: "Collected",
      description: `${sample.kind} collected from ${sample.subject}.`,
      time: formatCustodyTime(sample.collectedAt),
      dateTime: sample.collectedAt,
    },
    {
      id: "accessioned",
      title: "Accessioned",
      description: sample.accession,
      time: formatCustodyTime(sample.receivedAt),
      dateTime: sample.receivedAt,
      status: "success",
    },
    {
      id: "stored",
      title: "Stored",
      description: formatLocation(sample.location),
      time: formatCustodyTime(sample.storedAt),
      dateTime: sample.storedAt,
      status: "success",
      meta: sample.custodian,
    },
  ];

  if (sample.lastAction) {
    items.push({
      id: "last-action",
      title: ACTION_LABEL[sample.lastAction.kind],
      description: sample.lastAction.note,
      time: formatCustodyTime(sample.lastAction.at),
      dateTime: sample.lastAction.at,
      status: ACTION_STATUS[sample.lastAction.kind],
      meta: sample.lastAction.actor,
    });
  }

  return items;
}

export function SampleRecord({
  sample,
  onRunOpen,
}: {
  sample: RegistrySample | null;
  onRunOpen?: (runId: string) => void;
}): React.ReactElement {
  if (!sample) {
    return (
      <div
        className="flex h-full min-h-48 flex-col items-center justify-center gap-2 p-6 text-center"
        data-slot="sample-record-empty"
      >
        <InboxIcon
          aria-hidden="true"
          className="size-5 text-muted-foreground"
        />
        <p className="font-medium text-sm">No sample selected</p>
        <p className="max-w-52 text-muted-foreground text-xs leading-relaxed">
          Choose a row to see storage, aliquots, and the full chain of custody.
        </p>
      </div>
    );
  }

  return (
    <div className="grid gap-4 print:max-w-3xl" data-slot="sample-record">
      <header className="min-w-0">
        <p className="font-mono text-[10px] text-muted-foreground uppercase tracking-wide">
          {sample.accession}
        </p>
        <div className="mt-1 flex flex-wrap items-center gap-2">
          <h2 className="font-mono font-semibold text-lg">{sample.id}</h2>
          <StatusBadge
            label={STATUS_LABEL[sample.status]}
            size="sm"
            status={STATUS[sample.status]}
          />
        </div>
        <p className="mt-1 text-xs">
          <span className="font-medium">{sample.study}</span>{" "}
          <span className="text-muted-foreground">
            · {STUDY_TITLE[sample.study]}
          </span>
        </p>
        <p className="text-muted-foreground text-xs">
          Subject{" "}
          <span className="font-mono text-foreground">{sample.subject}</span>
        </p>
      </header>

      {sample.quarantineReason ? (
        <div
          className="flex gap-2 rounded-lg border border-warning/40 bg-warning/8 p-2.5 text-xs leading-relaxed"
          data-slot="sample-quarantine"
        >
          <AlertTriangleIcon
            aria-hidden="true"
            className="mt-0.5 size-3.5 shrink-0 text-warning"
          />
          <p>{sample.quarantineReason}</p>
        </div>
      ) : null}

      {sample.note ? (
        <p className="text-muted-foreground text-xs leading-relaxed">
          {sample.note}
        </p>
      ) : null}

      <section aria-label="Storage" className="grid gap-2 border-t pt-3">
        <h3 className="font-medium text-xs text-muted-foreground">Storage</h3>
        <dl className="grid gap-1.5 text-[11px]">
          <Fact label="Type" value={sample.kind} />
          <Fact label="Location" mono value={formatLocation(sample.location)} />
          <Fact
            label="Volume"
            mono
            title={
              sample.volumeUl === null ? "Volume was not recorded" : undefined
            }
            value={formatVolume(sample.volumeUl)}
          />
          <Fact label="Custodian" value={sample.custodian} />
          <Fact
            label="Collected"
            mono
            value={formatDateTime(sample.collectedAt)}
          />
          <Fact
            label="Received"
            mono
            value={formatDateTime(sample.receivedAt)}
          />
          {sample.parentId ? (
            <Fact label="Parent" mono value={sample.parentId} />
          ) : null}
        </dl>
        <p className="text-[10px] text-muted-foreground">
          All times UTC. Volume is the amount remaining in the parent tube.
        </p>
      </section>

      <section aria-label="Linked runs" className="grid gap-2 border-t pt-3">
        <h3 className="font-medium text-xs text-muted-foreground">
          Linked runs
        </h3>
        {sample.runIds.length === 0 ? (
          <p className="text-muted-foreground text-xs">
            No runs have used this sample.
          </p>
        ) : (
          <ul className="flex flex-wrap gap-1.5">
            {sample.runIds.map((runId) => (
              <li key={runId}>
                {onRunOpen ? (
                  <Button
                    onClick={() => onRunOpen(runId)}
                    size="xs"
                    type="button"
                    variant="outline"
                  >
                    <span className="font-mono">{runId}</span>
                    <ArrowUpRightIcon />
                  </Button>
                ) : (
                  <span className="font-mono text-xs">{runId}</span>
                )}
              </li>
            ))}
          </ul>
        )}
      </section>

      <section aria-label="Aliquots" className="grid gap-2 border-t pt-3">
        <div className="flex items-baseline justify-between gap-2">
          <h3 className="font-medium text-xs text-muted-foreground">
            Aliquots
          </h3>
          <p className="font-mono text-[10px] text-muted-foreground tabular-nums">
            {sample.aliquots.length}
          </p>
        </div>
        {sample.aliquots.length === 0 ? (
          <p className="text-muted-foreground text-xs">No aliquots recorded.</p>
        ) : (
          <ul className="grid gap-1.5">
            {sample.aliquots.map((aliquot) => (
              <li
                className="flex items-center justify-between gap-2 rounded-md border px-2 py-1.5"
                key={aliquot.id}
              >
                <span className="min-w-0">
                  <span className="block truncate font-mono text-[11px]">
                    {aliquot.id}
                  </span>
                  <span className="block text-[10px] text-muted-foreground">
                    {aliquot.location}
                  </span>
                </span>
                <span className="flex shrink-0 items-center gap-2">
                  <span className="font-mono text-[10px] tabular-nums">
                    {formatVolume(aliquot.volumeUl)}
                  </span>
                  <StatusBadge
                    label={ALIQUOT_LABEL[aliquot.status]}
                    size="sm"
                    status={ALIQUOT_STATUS[aliquot.status]}
                  />
                </span>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section
        aria-label="Chain of custody"
        className="grid gap-2 border-t pt-3"
      >
        <h3 className="font-medium text-xs text-muted-foreground">
          Chain of custody
        </h3>
        <Timeline
          items={buildCustody(sample)}
          label={`Chain of custody for ${sample.id}`}
        />
      </section>
    </div>
  );
}

function Fact({
  label,
  value,
  mono = false,
  title,
}: {
  label: string;
  value: string;
  mono?: boolean;
  title?: string;
}): React.ReactElement {
  return (
    <div className="flex items-start justify-between gap-3">
      <dt className="shrink-0 text-muted-foreground">{label}</dt>
      <dd className={cn("text-end", mono && "font-mono")} title={title}>
        {value}
      </dd>
    </div>
  );
}

"use client";

import {
  AlertTriangleIcon,
  DownloadIcon,
  LockIcon,
  PrinterIcon,
  RefreshCwIcon,
  WifiOffIcon,
} from "lucide-react";
import * as React from "react";
import {
  DataTable,
  type DataTableColumn,
} from "@/registry/default/instruments/data-table";
import { Stat, StatGrid } from "@/registry/default/instruments/stat";
import { StatusBadge } from "@/registry/default/instruments/status-badge";
import { cn } from "@/registry/default/lib/utils";
import { Button } from "@/registry/default/ui/button";
import {
  filterSamples,
  formatDate,
  formatLocation,
  formatShortDate,
  summarize,
  toCsv,
  uniqueStudies,
} from "./adapter";
import { FilterRail } from "./filter-rail";
import { MOCK_AS_OF, MOCK_SAMPLES } from "./mock-data";
import { SampleRecord } from "./sample-record";
import {
  isRegistryStatus,
  isSampleKind,
  isStudy,
  REGISTRY_STATUSES,
  type RegistryFilters,
  type RegistrySample,
  SAMPLE_KINDS,
  STATUS,
  STATUS_LABEL,
  STUDIES,
  type Study,
} from "./types";

const COLUMNS: DataTableColumn<RegistrySample>[] = [
  {
    id: "sample",
    header: "Sample",
    width: "7rem",
    cell: (row) => (
      <span className="inline-grid gap-0.5">
        <span className="font-mono text-xs">{row.id}</span>
        <span className="text-[10px] text-muted-foreground leading-none md:hidden">
          {row.kind}
        </span>
      </span>
    ),
    sortValue: (row) => row.id,
  },
  {
    id: "study",
    header: "Study",
    width: "7rem",
    className: "hidden lg:table-cell print:table-cell",
    cell: (row) => <span className="text-xs">{row.study}</span>,
    sortValue: (row) => row.study,
  },
  {
    id: "kind",
    header: "Type",
    width: "5rem",
    className: "hidden md:table-cell print:table-cell",
    cell: (row) => <span className="text-xs">{row.kind}</span>,
    sortValue: (row) => row.kind,
  },
  {
    id: "status",
    header: "Status",
    className: "hidden sm:table-cell print:table-cell",
    cell: (row) => (
      <StatusBadge
        label={STATUS_LABEL[row.status]}
        size="sm"
        status={STATUS[row.status]}
      />
    ),
    sortValue: (row) => STATUS_LABEL[row.status],
  },
  {
    id: "location",
    header: "Location",
    width: "9rem",
    className: "hidden xl:table-cell print:table-cell",
    cell: (row) => (
      <span className="font-mono text-[11px] text-muted-foreground">
        {formatLocation(row.location)}
      </span>
    ),
    sortValue: (row) => formatLocation(row.location),
  },
  {
    id: "volume",
    header: "Volume",
    unit: "µL",
    align: "end",
    numeric: true,
    width: "5rem",
    cell: (row) =>
      row.volumeUl === null ? (
        <span className="text-muted-foreground" title="Volume was not recorded">
          —
        </span>
      ) : (
        <span className="font-mono text-xs tabular-nums">
          {row.volumeUl.toLocaleString("en-GB")}
        </span>
      ),
    sortValue: (row) => row.volumeUl,
  },
  {
    id: "received",
    header: "Received",
    align: "end",
    width: "6rem",
    cell: (row) => (
      <span className="font-mono text-[11px] text-muted-foreground tabular-nums">
        {formatShortDate(row.receivedAt)}
      </span>
    ),
    sortValue: (row) => row.receivedAt,
  },
];

export type SampleRegistryProps = Omit<
  React.ComponentProps<"section">,
  "children" | "title"
> & {
  samples?: readonly RegistrySample[];
  headingLevel?: "h1" | "h2";
  title?: string;
  subtitle?: string;
  /** ISO 8601 timestamp for the last registry sync. */
  asOf?: string;
  loading?: boolean;
  error?: string | null;
  denied?: boolean;
  offline?: boolean;
  onRetry?: () => void;
  /** Open a linked run in the run report. */
  onRunOpen?: (runId: string) => void;
  /** Keep filters, sort, and the open sample in the address bar. */
  syncToUrl?: boolean;
};

export function SampleRegistry({
  samples = MOCK_SAMPLES,
  headingLevel = "h1",
  title = "Sample registry",
  subtitle = "LAB-03 · Bay 3",
  asOf = MOCK_AS_OF,
  loading = false,
  error = null,
  denied = false,
  offline = false,
  onRetry,
  onRunOpen,
  syncToUrl = false,
  className,
  ...props
}: SampleRegistryProps): React.ReactElement {
  const Heading = headingLevel;
  const [filters, setFilters] = React.useState<RegistryFilters>({
    query: "",
    study: "all",
    kind: "all",
    status: "all",
  });
  const [activeId, setActiveId] = React.useState<string | null>(
    samples[0]?.id ?? null,
  );
  const [urlReady, setUrlReady] = React.useState(!syncToUrl);

  const samplesRef = React.useRef(samples);
  samplesRef.current = samples;

  const filtered = React.useMemo(
    () => filterSamples(samples, filters),
    [samples, filters],
  );
  const summary = React.useMemo(() => summarize(filtered), [filtered]);
  const active = samples.find((sample) => sample.id === activeId) ?? null;

  React.useEffect(() => {
    if (!filtered.some((sample) => sample.id === activeId)) {
      setActiveId(filtered[0]?.id ?? null);
    }
  }, [filtered, activeId]);

  React.useEffect(() => {
    if (!syncToUrl) {
      return;
    }
    const params = new URLSearchParams(window.location.search);
    const query = params.get("q");
    const study = params.get("study");
    const kind = params.get("kind");
    const status = params.get("status");
    const sample = params.get("sample");

    setFilters((current) => ({
      query: query ?? current.query,
      study: isStudy(study) ? study : current.study,
      kind: isSampleKind(kind) ? kind : current.kind,
      status: isRegistryStatus(status) ? status : current.status,
    }));
    if (sample && samplesRef.current.some((entry) => entry.id === sample)) {
      setActiveId(sample);
    }
    setUrlReady(true);
  }, [syncToUrl]);

  React.useEffect(() => {
    if (!syncToUrl || !urlReady) {
      return;
    }
    const url = new URL(window.location.href);
    const set = (key: string, value: string) => {
      if (value) {
        url.searchParams.set(key, value);
      } else {
        url.searchParams.delete(key);
      }
    };
    set("q", filters.query.trim());
    set("study", filters.study === "all" ? "" : filters.study);
    set("kind", filters.kind === "all" ? "" : filters.kind);
    set("status", filters.status === "all" ? "" : filters.status);
    set("sample", activeId ?? "");
    window.history.replaceState(
      null,
      "",
      `${url.pathname}${url.search}${url.hash}`,
    );
  }, [syncToUrl, urlReady, filters, activeId]);

  const statusCounts = React.useMemo(() => {
    const counts = { all: samples.length } as Record<
      "all" | (typeof REGISTRY_STATUSES)[number],
      number
    >;
    for (const status of REGISTRY_STATUSES) {
      counts[status] = 0;
    }
    for (const sample of samples) {
      counts[sample.status] += 1;
    }
    return counts;
  }, [samples]);

  const studyCounts = React.useMemo(() => {
    const counts = { all: samples.length } as Record<"all" | Study, number>;
    for (const study of STUDIES) {
      counts[study] = 0;
    }
    for (const sample of samples) {
      counts[sample.study] += 1;
    }
    return counts;
  }, [samples]);

  const kindCounts = React.useMemo(() => {
    const counts = { all: samples.length } as Record<
      "all" | (typeof SAMPLE_KINDS)[number],
      number
    >;
    for (const kind of SAMPLE_KINDS) {
      counts[kind] = 0;
    }
    for (const sample of samples) {
      counts[sample.kind] += 1;
    }
    return counts;
  }, [samples]);

  const activeFilterCount =
    (filters.query.trim() ? 1 : 0) +
    (filters.study !== "all" ? 1 : 0) +
    (filters.kind !== "all" ? 1 : 0) +
    (filters.status !== "all" ? 1 : 0);

  const studyTotal = React.useMemo(() => uniqueStudies(samples), [samples]);

  function updateFilters(patch: Partial<RegistryFilters>) {
    setFilters((current) => ({ ...current, ...patch }));
  }

  function resetFilters() {
    setFilters({ query: "", study: "all", kind: "all", status: "all" });
  }

  function handleExport() {
    if (filtered.length === 0) {
      return;
    }
    const blob = new Blob([toCsv(filtered)], {
      type: "text/csv;charset=utf-8",
    });
    const url = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = url;
    link.download = "sample-registry.csv";
    document.body.append(link);
    link.click();
    link.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 0);
  }

  const state = loading
    ? "loading"
    : error
      ? "error"
      : denied
        ? "denied"
        : "ready";

  return (
    <section
      className={cn(
        "overflow-hidden rounded-xl border bg-background text-sm",
        "print:overflow-visible print:rounded-none print:border-0",
        className,
      )}
      data-slot="sample-registry"
      {...props}
    >
      <div className="hidden print:block print:pb-2">
        <p className="font-heading font-semibold text-lg">{title}</p>
        <p className="text-muted-foreground text-xs">
          {filtered.length} of {samples.length} samples · {subtitle} ·{" "}
          {formatDate(asOf)} · UTC
        </p>
      </div>

      <header className="flex flex-wrap items-start justify-between gap-3 border-b px-4 py-3 print:hidden">
        <div className="min-w-0">
          <p className="font-mono text-[11px] text-muted-foreground uppercase tracking-wide">
            Registry · {subtitle}
          </p>
          <Heading className="font-heading font-semibold text-xl tracking-tight">
            {title}
          </Heading>
          <p className="text-muted-foreground text-xs">
            {samples.length} samples across {studyTotal} studies · updated{" "}
            {formatDate(asOf)}
          </p>
        </div>
        <div className="flex items-center gap-2">
          <Button
            disabled={state !== "ready" || filtered.length === 0}
            onClick={handleExport}
            size="sm"
            type="button"
            variant="outline"
          >
            <DownloadIcon />
            Export CSV
          </Button>
          <Button
            disabled={state !== "ready"}
            onClick={() => window.print()}
            size="sm"
            type="button"
            variant="outline"
          >
            <PrinterIcon />
            Print
          </Button>
        </div>
      </header>

      {offline && state === "ready" ? (
        <div
          className="flex items-center gap-2 border-b bg-muted/40 px-4 py-2 text-xs print:hidden"
          role="status"
        >
          <WifiOffIcon aria-hidden="true" className="size-3.5" />
          <p>
            <span className="font-medium">Offline.</span> Showing the cached
            registry. Filters and export stay local.
          </p>
        </div>
      ) : null}

      {state === "loading" ? <LoadingState /> : null}

      {state === "error" ? (
        <StatePanel
          action={
            <Button
              onClick={
                onRetry ??
                (() => {
                  window.location.reload();
                })
              }
              size="sm"
              type="button"
              variant="outline"
            >
              <RefreshCwIcon />
              Retry
            </Button>
          }
          icon={<AlertTriangleIcon aria-hidden="true" className="size-5" />}
          message={
            error ??
            "The registry service did not respond. Nothing was removed from storage."
          }
          title="Could not load the registry"
        />
      ) : null}

      {state === "denied" ? (
        <StatePanel
          icon={<LockIcon aria-hidden="true" className="size-5" />}
          message="Registry records are restricted to the lab’s members. Ask a custodian for access."
          title="You don’t have access to this registry"
        />
      ) : null}

      {state === "ready" ? (
        <>
          <StatGrid className="m-3 sm:m-4 print:mx-0" columns={4}>
            <Stat
              hint={`of ${samples.length} in the registry`}
              label="Samples"
              value={summary.count}
            />
            <Stat
              hint={
                summary.missingVolume === 0
                  ? "All volumes recorded"
                  : `${summary.missingVolume} missing volume${
                      summary.missingVolume === 1 ? "" : "s"
                    }`
              }
              label="Stored"
              value={summary.stored}
            />
            <Stat
              hint="checked out to runs"
              label="In use"
              value={summary.inUse}
            />
            <Stat
              hint="excluded from runs"
              label="Quarantined"
              value={summary.quarantined}
            />
          </StatGrid>

          <div className="grid border-t lg:grid-cols-[13rem_minmax(0,1fr)_21rem] print:block print:border-t-0">
            <FilterRail
              activeCount={activeFilterCount}
              filters={filters}
              kindCounts={kindCounts}
              onChange={updateFilters}
              onReset={resetFilters}
              statusCounts={statusCounts}
              studyCounts={studyCounts}
            />

            <div className="min-w-0">
              <DataTable
                activeRowId={activeId ?? undefined}
                className="rounded-none border-0"
                columns={COLUMNS}
                defaultSort={{ columnId: "received", direction: "desc" }}
                emptyLabel={
                  <div className="grid justify-items-center gap-2 py-4">
                    <p>
                      {samples.length === 0
                        ? "No samples in the registry."
                        : "No samples match these filters."}
                    </p>
                    {samples.length > 0 ? (
                      <Button
                        onClick={resetFilters}
                        size="xs"
                        type="button"
                        variant="outline"
                      >
                        Reset filters
                      </Button>
                    ) : null}
                  </div>
                }
                getRowId={(sample) => sample.id}
                getRowLabel={(sample) => sample.id}
                label="Registry samples"
                onRowActivate={(id) => setActiveId(id)}
                rows={filtered}
                title="Samples"
              />
            </div>

            <aside
              aria-label="Sample record"
              className="border-t p-4 lg:border-s lg:border-t-0 print:border-t print:pt-4"
            >
              <SampleRecord onRunOpen={onRunOpen} sample={active} />
            </aside>
          </div>
        </>
      ) : null}
    </section>
  );
}

function StatePanel({
  icon,
  title,
  message,
  action,
}: {
  icon: React.ReactNode;
  title: string;
  message: string;
  action?: React.ReactNode;
}): React.ReactElement {
  return (
    <div
      className="grid justify-items-center gap-2 px-6 py-16 text-center"
      role="alert"
    >
      <span className="text-muted-foreground">{icon}</span>
      <h2 className="font-medium">{title}</h2>
      <p className="max-w-sm text-muted-foreground text-sm leading-relaxed">
        {message}
      </p>
      {action}
    </div>
  );
}

function LoadingState(): React.ReactElement {
  return (
    <div aria-busy="true" aria-live="polite" className="grid gap-3 p-4">
      <span className="sr-only">Loading sample registry…</span>
      <div className="grid gap-px overflow-hidden rounded-xl border bg-border sm:grid-cols-2 lg:grid-cols-4">
        {[0, 1, 2, 3].map((index) => (
          <div className="bg-background p-4" key={index}>
            <div className="h-3 w-20 rounded bg-muted motion-safe:animate-pulse" />
            <div className="mt-3 h-6 w-24 rounded bg-muted motion-safe:animate-pulse" />
          </div>
        ))}
      </div>
      <div className="grid gap-3 lg:grid-cols-[13rem_minmax(0,1fr)]">
        <div className="h-72 rounded-xl border bg-muted/32" />
        <div className="grid gap-3">
          <div className="h-10 rounded-xl border bg-muted/32" />
          <div className="h-72 rounded-xl border bg-muted/32" />
        </div>
      </div>
    </div>
  );
}
